import { assetUrl } from '../lib/assets'
import { snapshotManifest } from '../lib/catalog'
import type { Product, SnapshotFraming } from '../lib/types'

interface Props {
  product: Product
  framing: SnapshotFraming
  sizes: string
  className?: string
  eager?: boolean
}

/** Pre-rendered transparent snapshot of the default configuration (generated by `pnpm snapshots`). */
export default function SnapshotImage({ product, framing, sizes, className = '', eager = false }: Props) {
  const image = snapshotManifest.images[product.slug]?.[framing]
  if (!image) {
    return (
      <div className={`flex items-center justify-center font-serif text-5xl text-stone-300 ${className}`} aria-hidden="true">
        {product.name.charAt(0)}
      </div>
    )
  }
  return (
    <img
      src={assetUrl(image.path)}
      srcSet={image.srcset.map((s) => `${assetUrl(s.path)} ${s.width}w`).join(', ')}
      sizes={sizes}
      width={image.width}
      height={image.height}
      alt={product.name}
      loading={eager ? 'eager' : 'lazy'}
      fetchPriority={eager ? 'high' : undefined}
      decoding="async"
      draggable={false}
      className={`object-contain select-none ${className}`}
    />
  )
}
